<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Service\Visibility\UserFederatedIdentityVisibilityService;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityQueryRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserFederatedIdentityVisibilityService $visibility,
        private readonly UserFederatedIdentityQueryRepositoryGateway $reader
    ) {
    }

    public function allowRetrieve(?UserFederatedIdentityRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for User federated identity");
        $span = $this->startSpan("Check allow of retrieve usecase for User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?UserFederatedIdentityRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for User federated identity");
        $span = $this->startSpan("Check hidden fields usecase for User federated identity");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): UserFederatedIdentityRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for User federated identity");
        $span = $this->startSpan("Run retrieve usecase for User federated identity");
        try {
            $ref = new UserFederatedIdentityRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve User federated identity');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserFederatedIdentityRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
